pub fn zh_tier(tier: &str) -> &'static [&'static str] {
    match tier {
        "easy" => ZH_EASY,
        "medium" => ZH_MEDIUM,
        "hard" => ZH_HARD,
        "expert" => ZH_EXPERT,
        _ => ZH_MEDIUM,
    }
}

/// Word bank for a built-in language + tier (English by default).
pub fn tier_for(lang: &str, tier: &str) -> &'static [&'static str] {
    use crate::consts::{AR, DE, ES, FIL, FR, HI, JA, KO, PL, PT, RU, SW, VI, ZH};
    match lang {
        // Russian shipped a real production bank (CC-MASTER-PARITY Track R):
        // Leipzig CC BY, frequency-ranked, length-tiered, gated by build-wordlists.
        RU => simple_tier(RU_EASY, RU_MEDIUM, RU_HARD, RU_EXPERT, tier),
        SW => simple_tier(SW_EASY, SW_MEDIUM, SW_HARD, SW_EXPERT, tier),
        // Arabic UNGATED and Hindi PROMOTED (Eric's rulings, 2026-07-25): both
        // serve production banks (assets/words/{ar,hi}/ via build-wordlists,
        // keyboard-reachability gated). No registered language is contentless
        // anymore — the serves-its-OWN-bank test below is the fallthrough tripwire.
        AR => simple_tier(AR_EASY, AR_MEDIUM, AR_HARD, AR_EXPERT, tier),
        // Persian. Unreachable until fa enters the registry — that reverses
        // CC-MASTER-PARITY Phase A and is Eric's call — but wired the same way
        // the fa keyboard is, so the bank is serveable the moment it lands
        // rather than needing a second pass to remember this arm exists.
        "fa" => simple_tier(FA_EASY, FA_MEDIUM, FA_HARD, FA_EXPERT, tier),
        HI => simple_tier(HI_EASY, HI_MEDIUM, HI_HARD, HI_EXPERT, tier),
        ES => es_tier(tier),
        FR => simple_tier(FR_EASY, FR_MEDIUM, FR_HARD, FR_EXPERT, tier),
        DE => simple_tier(DE_EASY, DE_MEDIUM, DE_HARD, DE_EXPERT, tier),
        PT => simple_tier(PT_EASY, PT_MEDIUM, PT_HARD, PT_EXPERT, tier),
        PL => simple_tier(PL_EASY, PL_MEDIUM, PL_HARD, PL_EXPERT, tier),
        VI => simple_tier(VI_EASY, VI_MEDIUM, VI_HARD, VI_EXPERT, tier),
        KO => simple_tier(KO_EASY, KO_MEDIUM, KO_HARD, KO_EXPERT, tier),
        JA => simple_tier(JA_EASY, JA_MEDIUM, JA_HARD, JA_EXPERT, tier),
        FIL => simple_tier(FIL_EASY, FIL_MEDIUM, FIL_HARD, FIL_EXPERT, tier),
        ZH => zh_tier(tier),
        _ => en_tier(tier),
    }
}

#[cfg(test)]
mod content_tests {
    use crate::consts::{BUILTIN_LANGS, TIER_ORDER};

    /// THE fallthrough tripwire, structural since Hindi's 2026-07-25 promotion
    /// left no contentless registered language: every registered language must
    /// serve its OWN non-empty bank — never the English bank wearing its name.
    /// `tier_for` ends in `_ => en_tier(tier)`, so a new registry entry without
    /// an explicit arm silently inherits English words; the pointer inequality
    /// below catches exactly that.
    #[test]
    fn every_registered_language_serves_its_own_bank() {
        for (code, _, _, _) in BUILTIN_LANGS.iter() {
            for tier in TIER_ORDER {
                let bank = super::tier_for(code, tier);
                assert!(!bank.is_empty(), "{code}/{tier} lost its bank");
                if *code != "en" {
                    assert_ne!(
                        bank.as_ptr(),
                        super::en_tier(tier).as_ptr(),
                        "{code}/{tier} fell through to the ENGLISH bank — add its arm"
                    );
                }
            }
        }
    }
}

#[cfg(test)]
mod tier_dump {
    //! Read-only diagnostic support: dump exactly what `tier_for` ships, for the
    //! tier-health report. Ignored by default; run explicitly:
    //!   cargo test --lib tier_dump::dump -- --ignored --nocapture
    use crate::consts::BUILTIN_LANGS;

    #[test]
    #[ignore]
    fn dump() {
        let tiers = ["easy", "medium", "hard", "expert"];
        let mut obj = String::from("{\n");
        for (li, (lang, _, _, _)) in BUILTIN_LANGS.iter().enumerate() {
            obj.push_str(&format!("  \"{lang}\": {{\n"));
            for (ti, tier) in tiers.iter().enumerate() {
                let words = super::tier_for(lang, tier);
                let items: Vec<String> = words
                    .iter()
                    // raw UTF-8, JSON-escape only " and \ (keep CJK scripts literal)
                    .map(|w| format!("\"{}\"", w.replace('\\', "\\\\").replace('"', "\\\"")))
                    .collect();
                let comma = if ti + 1 < tiers.len() { "," } else { "" };
                obj.push_str(&format!("    \"{tier}\": [{}]{comma}\n", items.join(", ")));
            }
            let comma = if li + 1 < BUILTIN_LANGS.len() { "," } else { "" };
            obj.push_str(&format!("  }}{comma}\n"));
        }
        obj.push_str("}\n");
        std::fs::write("tools/tierhealth/tiers_dump.json", obj).expect("write dump");
        eprintln!("wrote tools/tierhealth/tiers_dump.json");
    }
}

#[cfg(test)]
mod pool_dump {
    /// v8 tooling: dump tier pools for the offline scanlock tools
    /// (`WP_POOL_DIR=... cargo test dump_pools -- --ignored`).
    #[test]
    #[ignore]
    fn dump_pools() {
        let Ok(dir) = std::env::var("WP_POOL_DIR") else { return };
        std::fs::create_dir_all(&dir).unwrap();
        for (code, _, _, _) in crate::consts::BUILTIN_LANGS.iter() {
            for tier in ["easy", "medium", "hard", "expert"] {
                let pool = super::tier_for(code, tier);
                let mut out = String::from("[");
                for (i, w) in pool.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    out.push('"');
                    for c in w.chars() {
                        if c == '"' || c == '\\' {
                            out.push('\\');
                        }
                        out.push(c);
                    }
                    out.push('"');
                }
                out.push(']');
                std::fs::write(format!("{dir}/{code}-{tier}.json"), out).unwrap();
            }
        }
    }
}

#[cfg(test)]
mod tier_ladder_tests {
    /// CC-PLAYER-CONTRACT P5 — a given tier means comparable difficulty in
    /// every language.
    ///
    /// LENGTH IS A PROXY, AND FOR ko/ja IT IS THE WRONG ONE. Measured by
    /// character count, Korean looked broken: easy 4.71, medium 10.51, hard
    /// 9.80, expert 10.23 jamo. Re-measuring in jamo instead of characters
    /// confirmed the same shape, so the instrument seemed sound — but the
    /// dimension was wrong from the start. Measured by FREQUENCY, which is what
    /// difficulty means in a spelling game (you cannot spell a word you have
    /// never met), Korean already climbs: bands 405, 441, 493, 528.
    ///
    /// So ko and ja are EXCLUDED here and their ladders are verified on the
    /// frequency signal by tools/retier_cjk.py, which reads
    /// tools/wordpipe/sources/freq_{ko,ja}.txt. Those files are build inputs
    /// and gitignored, so a test cannot depend on them and still pass in a
    /// fresh clone.
    ///
    /// For the other thirteen banks length remains a fair proxy — they are
    /// alphabetic, and a longer word is more to spell — and this catches a
    /// tier that stops climbing.
    #[test]
    fn every_tier_ladder_climbs() {
        use unicode_normalization::UnicodeNormalization;
        let mean = |ws: &[&str]| -> f64 {
            if ws.is_empty() { return 0.0; }
            ws.iter().map(|w| {
                let base = w.split('|').next().unwrap_or(w);
                base.nfd().count() as f64
            }).sum::<f64>() / ws.len() as f64
        };
        let mut checked = 0;
        for lang in crate::consts::BUILTIN_LANGS.iter().map(|(c, _, _, _)| *c) {
            // See the note above: their difficulty is frequency-ordered.
            if lang == "ko" || lang == "ja" {
                continue;
            }
            let tiers = ["easy", "medium", "hard", "expert"];
            let means: Vec<f64> = tiers.iter().map(|t| mean(crate::words::tier_for(lang, t))).collect();
            if means.iter().any(|m| *m == 0.0) { continue; }
            checked += 1;
            for i in 1..means.len() {
                assert!(means[i] > means[i - 1],
                    "{lang}: {} ({:.2}) is not harder than {} ({:.2}) — a tier that \
                     does not climb tells the player nothing",
                    tiers[i], means[i], tiers[i - 1], means[i - 1]);
            }
        }
        assert!(checked >= 10, "expected the built-in banks, saw {checked}");
    }
}
